contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner, address admin, bool access) public payable {
        require(true);
        bool transferOk;
        bool adminCallReverted;
        bool secondTransferReverted;
        try c.transferOwnership(newOwner) {
            transferOk = true;
        } catch {
            transferOk = false;
        }
        if (transferOk) {
            try c.adjustAdminAccess(admin, access) {
                adminCallReverted = false;
            } catch {
                adminCallReverted = true;
            }
            try c.transferOwnership(address(this)) {
                secondTransferReverted = false;
            } catch {
                secondTransferReverted = true;
            }
        }
        assert(!transferOk || (adminCallReverted && secondTransferReverted));
    }
    receive() external payable {}
}

