contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address otherClaimer) public payable {
        require(otherClaimer != address(0));

        // Snapshot before the deciding call (read-only surface).
        uint256 unclaimedBeforeSelf = c.getUnclaimedRewards(address(this));
        uint256 unclaimedBeforeOther = c.getUnclaimedRewards(otherClaimer);
        uint32 roundsClaimedBefore = c.numRoundsClaimed(address(this));
        uint256 roundIdBefore = c.roundId();

        // Fresh contract with no completed rounds: claimRewards must be a safe no-op.
        // Use try/catch to observe revert without failing the whole transaction.
        bool reverted;
        string[] memory noURIs = new string[](0);
        string[] memory noTypes = new string[](0);
        uint256[2][] memory noAttrs = new uint256[2][](0);
        try c.claimRewards(noURIs, noTypes, noAttrs) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Post-state reads.
        uint256 unclaimedAfterSelf = c.getUnclaimedRewards(address(this));
        uint256 unclaimedAfterOther = c.getUnclaimedRewards(otherClaimer);
        uint32 roundsClaimedAfter = c.numRoundsClaimed(address(this));
        uint256 roundIdAfter = c.roundId();

        assert(
            !reverted &&
            unclaimedBeforeSelf == 0 &&
            unclaimedBeforeOther == 0 &&
            unclaimedAfterSelf == unclaimedBeforeSelf &&
            unclaimedAfterOther == unclaimedBeforeOther &&
            roundsClaimedAfter == roundsClaimedBefore &&
            roundIdAfter == roundIdBefore
        );
    }

    receive() external payable {}
}

