    constructor(C _c) { c = _c; }
    function run() public payable {
        require(true);
        // On a fresh contract the caller has claimed nothing and no winners exist yet,
        // so the caller has zero unclaimed rewards.
        uint256 beforeUnclaimed = c.getUnclaimedRewards(address(this));
        uint256 beforeRoundId = c.roundId();
        uint32 beforeClaimed = c.numRoundsClaimed(address(this));

        // The deciding call: attempt to claim rewards with empty model data.
