        string[] memory emptyTypes = new string[](0);
        uint256[2][] memory emptyAttrs = new uint256[2][](0);
        bool reverted;
        try c.claimRewards(emptyHashes, emptyTypes, emptyAttrs) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterUnclaimed = c.getUnclaimedRewards(address(this));
        uint256 afterRoundId = c.roundId();
        uint32 afterClaimed = c.numRoundsClaimed(address(this));

        assert(
            !reverted &&
            beforeUnclaimed == 0 &&
            afterUnclaimed == 0 &&
            afterRoundId == beforeRoundId &&
            afterClaimed == beforeClaimed
        );
    }
    receive() external payable {}
}

