contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 fakeWinnerToken) public payable {
        require(true);
        uint256 beforeRoundId = c.roundId();
        bool adminFlag = c.isAdmin(address(this));

        // Even with the correct winners length, a non-admin must not be able to pick winners.
        uint256[] memory rightLen = new uint256[](c.winnersPerPeriod());
        for (uint256 i = 0; i < rightLen.length; i++) {
            rightLen[i] = fakeWinnerToken + i;
        }
        bool revertedRightLen;
        try c.pickWinner(rightLen) { revertedRightLen = false; } catch { revertedRightLen = true; }

        // A non-admin must not be able to grant itself admin access.
        bool revertedAdmin;
        try c.adjustAdminAccess(address(this), true) { revertedAdmin = false; } catch { revertedAdmin = true; }

        bool stillNotAdmin = !c.isAdmin(address(this));
        uint256 afterRoundId = c.roundId();

        assert(
            revertedRightLen &&
            revertedAdmin &&
            stillNotAdmin &&
            afterRoundId == beforeRoundId &&
            (adminFlag ? true : true)
        );
    }
    receive() external payable {}
}

